-- ============================================================================
-- db/pg10-proof.sql  --  GENERATED FILE.  THIS IS NOT A MIGRATION.
--
-- The migrations in db/migrations/, joined in filename order, so one file can be
-- carried to a PostgreSQL 10 server and applied there. It CONTAINS the
-- migrations: never put it in db/migrations/, and never apply it in addition to
-- them (the second CREATE FUNCTION would fail).
--
-- Do not edit it.  Regenerate:  node db/build-proof.mjs
--                  Is it stale: node db/build-proof.mjs --check
-- A stale proof file is worse than none.
--
-- Run it on an EMPTY database, with psql (the \echo and \set lines are psql
-- commands and other clients will not understand them):
--   psql -X -v ON_ERROR_STOP=1 -f pg10-proof.sql <connection>
-- Each migration keeps its own BEGIN/COMMIT; there is no outer transaction. If a
-- file fails it rolls back, but the files before it stay applied. Drop the
-- schema and start again; never patch a half-applied database.
--
-- psql reports  psql:pg10-proof.sql:LINE: ERROR: ...  Find LINE below. The line
-- inside the source file is  LINE - first + 1.  Lines are counted in THIS file.
--
--   001_foundation.sql               lines    44 -   173
--   002_staff_auth.sql               lines   175 -   263
--   003_visits.sql                   lines   265 -   423
--   004_enquiries.sql                lines   425 -   472
--   005_attendance.sql               lines   474 -   575
--   006_audit_log.sql                lines   577 -   618
--   007_handovers.sql                lines   620 -   707
--   008_case_links.sql               lines   709 -   790
--   009_attendance_device.sql        lines   792 -   862
--   010_roster_movements_backdating.sql lines   864 -  1018
--   011_entered_by_per_event.sql     lines  1020 -  1070
--   012_movement_entered_by_names.sql lines  1072 -  1101
--   013_signout_missing.sql          lines  1103 -  1152
--   014_corrections.sql              lines  1154 -  1217
--   015_movement_corrections.sql     lines  1219 -  1278
--   016_late_threshold_snapshot.sql  lines  1280 -  1329
--   017_visit_corrections.sql        lines  1331 -  1402
--   018_handover_corrections.sql     lines  1404 -  1488
-- ============================================================================
\set ON_ERROR_STOP on
\echo '>>> applying 001_foundation.sql'
-- 001 foundation: shared trigger functions and the small controlled lists.
--
-- Target: PostgreSQL 10.23. Rules every file in this directory follows:
--  - UUID primary keys are generated by the APP (crypto.randomUUID()); there is
--    no DEFAULT. gen_random_uuid() does not exist on 10. The one bigint key
--    (audit_log) uses an identity column, which 10 has.
--  - Every time is timestamptz and defaults to now(): the database is the one
--    clock (a browser clock can be wrong). The office zone is Africa/Lagos; day
--    boundaries are computed in queries with AT TIME ZONE 'Africa/Lagos', and
--    no local timestamp is ever stored. The only `date` columns are leave days.
--  - No ENUM types (ALTER TYPE ... ADD VALUE cannot run in a transaction before
--    12) and no generated columns (12+). Controlled lists are lookup tables with
--    foreign keys, so a new value is an INSERT, not a migration.
--  - Triggers use EXECUTE PROCEDURE (EXECUTE FUNCTION is 11+).
--  - No extensions are required.
--  - Each file is one transaction and is meant to be applied in filename order.

BEGIN;

-- Keeps updated_at honest even when application code forgets to set it.
CREATE FUNCTION touch_updated_at() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  NEW.updated_at := now();
  RETURN NEW;
END;
$$;

-- Makes a table append-only. Attach it for UPDATE/DELETE (per row) and for
-- TRUNCATE (per statement). It does not stop a superuser or the table owner from
-- dropping the trigger: the application's database role must also have no
-- UPDATE, DELETE or TRUNCATE grant on these tables (a deployment step, not part
-- of these files).
CREATE FUNCTION forbid_change() RETURNS trigger
LANGUAGE plpgsql AS $$
BEGIN
  RAISE EXCEPTION '% is append-only: % is not allowed', TG_TABLE_NAME, TG_OP
    USING ERRCODE = 'restrict_violation';
END;
$$;

-- ---------------------------------------------------------------------------
-- Staff roles. Roles are enforced in the application (no row-level security).
-- ---------------------------------------------------------------------------
CREATE TABLE role (
  code       text PRIMARY KEY CONSTRAINT role_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label      text NOT NULL,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO role (code, label) VALUES
  ('FRONT_DESK',  'Front desk'),
  ('LEGAL',       'Legal'),
  ('ADMIN',       'Admin'),
  ('SUPER_ADMIN', 'Super admin');

-- ---------------------------------------------------------------------------
-- Visitor types. Five, as on screen 04. "Existing" versus "new" is NOT a type:
-- it is the outcome of the lookup and lives on visit.lookup_outcome.
-- portal_lookup: only a Client searches the portal. The portal has client
-- endpoints only, so a Realtor is a non-client here until it exposes more.
-- ---------------------------------------------------------------------------
CREATE TABLE visitor_type (
  code          text PRIMARY KEY CONSTRAINT visitor_type_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label         text NOT NULL,
  portal_lookup boolean NOT NULL DEFAULT false,
  is_active     boolean NOT NULL DEFAULT true,
  sort_order    integer NOT NULL DEFAULT 0,
  created_at    timestamptz NOT NULL DEFAULT now()
);

INSERT INTO visitor_type (code, label, portal_lookup, sort_order) VALUES
  ('CLIENT',   'Client',   true,  1),
  ('REALTOR',  'Realtor',  false, 2),
  ('INVESTOR', 'Investor', false, 3),
  ('DELIVERY', 'Delivery', false, 4),
  ('VISITOR',  'Visitor',  false, 5);

-- ---------------------------------------------------------------------------
-- Visit reasons: the five chips on screen 04 (the PRD's list).
-- ---------------------------------------------------------------------------
CREATE TABLE visit_reason (
  code       text PRIMARY KEY CONSTRAINT visit_reason_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label      text NOT NULL,
  is_active  boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO visit_reason (code, label, sort_order) VALUES
  ('INQUIRY',             'Inquiry',             1),
  ('COMPLAINT',           'Complaint',           2),
  ('DOCUMENT_COLLECTION', 'Document collection', 3),
  ('CONTRACT_SIGNING',    'Contract signing',    4),
  ('SCHEDULED_MEETING',   'Scheduled meeting',   5);

-- ---------------------------------------------------------------------------
-- Enquiry topics (a non-client's enquiry, CLAUDE.md rule 3). Managed by Super
-- Admin. PLACEHOLDER SEED: the real list has not been supplied. COMMISSION_QUERY
-- comes from the original mockup's "B. Umeh, commission query".
-- ---------------------------------------------------------------------------
CREATE TABLE enquiry_topic (
  code       text PRIMARY KEY CONSTRAINT enquiry_topic_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label      text NOT NULL,
  is_active  boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO enquiry_topic (code, label, sort_order) VALUES
  ('COMMISSION_QUERY', 'Commission query', 1),
  ('OTHER',            'Other',            2);

-- ---------------------------------------------------------------------------
-- Leave kinds. Leave is minimal: dates and a kind. PLACEHOLDER SEED.
-- ---------------------------------------------------------------------------
CREATE TABLE leave_kind (
  code       text PRIMARY KEY CONSTRAINT leave_kind_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label      text NOT NULL,
  is_active  boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO leave_kind (code, label, sort_order) VALUES
  ('ANNUAL', 'Annual leave', 1),
  ('SICK',   'Sick leave',   2),
  ('OTHER',  'Other',        3);

COMMIT;
\echo '>>> applying 002_staff_auth.sql'
-- 002 staff and authentication: staff, their roles, registered desk devices and
-- sessions.
--
-- Everyone has individual credentials. A shared front-desk machine is a
-- registered `device`; on it a staff member may switch in with a PIN. Every
-- write carries a person (the session's staff_id), never "the desk".
--
-- Password and PIN hashes use scrypt from node:crypto (no dependency). Session
-- and device tokens are stored only as a SHA-256 hash; the raw token is never
-- stored. No staff phone, address or salary: not needed.

BEGIN;

CREATE TABLE staff (
  id                    uuid PRIMARY KEY,
  email                 text NOT NULL
    CONSTRAINT staff_email_format_check CHECK (email = btrim(email) AND position('@' in email) > 1),
  full_name             text NOT NULL
    CONSTRAINT staff_full_name_not_blank_check CHECK (btrim(full_name) <> ''),
  -- Free text for now: screen 08's filter chips are derived from the data, in
  -- order of first appearance.
  department            text NOT NULL
    CONSTRAINT staff_department_not_blank_check CHECK (btrim(department) <> ''),
  password_hash         text NOT NULL,
  must_change_password  boolean NOT NULL DEFAULT false,
  password_failed_count integer NOT NULL DEFAULT 0
    CONSTRAINT staff_password_failed_count_nonneg_check CHECK (password_failed_count >= 0),
  password_locked_until timestamptz,
  -- The PIN is only accepted on a registered desk device (an application rule).
  pin_hash              text,
  pin_failed_count      integer NOT NULL DEFAULT 0
    CONSTRAINT staff_pin_failed_count_nonneg_check CHECK (pin_failed_count >= 0),
  pin_locked_until      timestamptz,
  -- Staff are never deleted: visits and attendance point at them forever.
  is_active             boolean NOT NULL DEFAULT true,
  deactivated_at        timestamptz,
  created_at            timestamptz NOT NULL DEFAULT now(),
  updated_at            timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT staff_active_matches_deactivated_check CHECK (is_active = (deactivated_at IS NULL))
);

CREATE UNIQUE INDEX staff_email_lower_key ON staff (lower(email));

CREATE TRIGGER staff_touch_updated_at
  BEFORE UPDATE ON staff
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

-- One person, any number of roles (no "primary" role). What each role may do is
-- decided in the application.
CREATE TABLE staff_role (
  staff_id   uuid NOT NULL REFERENCES staff (id),
  role_code  text NOT NULL REFERENCES role (code),
  granted_by uuid REFERENCES staff (id),
  created_at timestamptz NOT NULL DEFAULT now(),
  PRIMARY KEY (staff_id, role_code)
);

-- A registered machine. DESK = the shared front-desk computer (PIN switching
-- and clock-in allowed). PERSONAL = someone's own machine.
CREATE TABLE device (
  id            uuid PRIMARY KEY,
  label         text NOT NULL
    CONSTRAINT device_label_not_blank_check CHECK (btrim(label) <> ''),
  kind          text NOT NULL
    CONSTRAINT device_kind_valid_check CHECK (kind IN ('DESK', 'PERSONAL')),
  token_hash    text NOT NULL CONSTRAINT device_token_hash_key UNIQUE,
  registered_by uuid NOT NULL REFERENCES staff (id),
  created_at    timestamptz NOT NULL DEFAULT now(),
  revoked_at    timestamptz
);

CREATE TABLE session (
  id           uuid PRIMARY KEY,
  staff_id     uuid NOT NULL REFERENCES staff (id),
  device_id    uuid REFERENCES device (id),
  token_hash   text NOT NULL CONSTRAINT session_token_hash_key UNIQUE,
  ip           inet,
  created_at   timestamptz NOT NULL DEFAULT now(),
  last_seen_at timestamptz NOT NULL DEFAULT now(),
  expires_at   timestamptz NOT NULL,
  revoked_at   timestamptz,
  CONSTRAINT session_expires_after_created_check CHECK (expires_at > created_at)
);

CREATE INDEX session_staff_idx ON session (staff_id);
-- Sessions that can still be used; expiry is checked against now() in the query.
CREATE INDEX session_live_idx ON session (expires_at) WHERE revoked_at IS NULL;

COMMIT;
\echo '>>> applying 003_visits.sql'
-- 003 visits: non-client visitors, the visit itself, and its timeline.
--
-- There is NO client table. A client is a portal record; CSS keeps only the
-- portal client id and the name AS LOGGED at the desk (see visit). Everything
-- else about a client is read from the portal on demand and never stored.
--
-- Elapsed time, on track / long / overdue, and total duration are derived in the
-- application from checked_in_at / checked_out_at. They are never stored.

BEGIN;

-- Non-clients only (a Realtor, Investor, Delivery, Visitor, or a Client the
-- portal could not find). Repeat visits are identified by a desk-CONFIRMED match
-- on this table, never an automatic merge.
CREATE TABLE visitor (
  id                      uuid PRIMARY KEY,
  display_name            text NOT NULL
    CONSTRAINT visitor_display_name_not_blank_check CHECK (btrim(display_name) <> ''),
  organisation            text,
  -- Typed by the desk and normalised to E.164. Optional: a courier may give none.
  phone                   text
    CONSTRAINT visitor_phone_e164_check CHECK (phone ~ '^\+[1-9][0-9]{6,14}$'),
  -- NDPR: consent is captured when the record is created.
  consent_at              timestamptz NOT NULL,
  -- Set by the desk if this person later becomes a portal client. Old visits stay
  -- enquiries; this replaces the PRD's phone reconciliation.
  linked_portal_client_id uuid,
  linked_at               timestamptz,
  linked_by               uuid REFERENCES staff (id),
  -- Duplicate resolution: the surviving record's id. Rows are not deleted.
  merged_into_id          uuid REFERENCES visitor (id),
  -- Erasure request: personal fields are blanked, the row and its visits stay.
  anonymised_at           timestamptz,
  created_by              uuid NOT NULL REFERENCES staff (id),
  created_at              timestamptz NOT NULL DEFAULT now(),
  updated_at              timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT visitor_not_merged_into_self_check
    CHECK (merged_into_id IS NULL OR merged_into_id <> id),
  CONSTRAINT visitor_link_time_matches_link_check
    CHECK ((linked_portal_client_id IS NULL) = (linked_at IS NULL)),
  CONSTRAINT visitor_link_staff_matches_link_check
    CHECK ((linked_portal_client_id IS NULL) = (linked_by IS NULL))
);

-- One live record per phone number. Merged records free their number.
CREATE UNIQUE INDEX visitor_phone_live_key ON visitor (phone)
  WHERE phone IS NOT NULL AND merged_into_id IS NULL;
CREATE INDEX visitor_name_idx ON visitor (lower(display_name));

CREATE TRIGGER visitor_touch_updated_at
  BEFORE UPDATE ON visitor
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

CREATE TABLE visit (
  id                uuid PRIMARY KEY,
  visitor_type_code text NOT NULL REFERENCES visitor_type (code),
  reason_code       text NOT NULL REFERENCES visit_reason (code),

  -- WHO. Exactly one of the two identities is set.
  --  portal_client_id    the portal's client id (a UUID in the portal's database,
  --                      so deliberately NO foreign key). The desk never sees it.
  --  client_name_logged  the name AS LOGGED at the desk, like a signature in a
  --                      visitor book. It is the ONE deliberate copy of portal
  --                      data: lists, exports and frequency reports cannot make a
  --                      portal call per row, and history must survive the portal
  --                      returning 404 for a client. NEVER refreshed. Screen 05
  --                      shows the LIVE portal name, not this one.
  --  visitor_id          a non-client.
  portal_client_id   uuid,
  client_name_logged text
    CONSTRAINT visit_client_name_not_blank_check
    CHECK (client_name_logged IS NULL OR btrim(client_name_logged) <> ''),
  visitor_id         uuid REFERENCES visitor (id),

  -- How identity was established. MATCHED is the only outcome with a portal client.
  -- NOT_LOOKED_UP: a non-client type, no search. NO_MATCH: searched, nobody chosen.
  -- PORTAL_UNAVAILABLE: the lookup failed; the desk went on without verification
  -- (check-in must not depend on the portal being up).
  lookup_outcome text NOT NULL
    CONSTRAINT visit_lookup_outcome_valid_check CHECK (lookup_outcome IN
      ('MATCHED', 'NO_MATCH', 'NOT_LOOKED_UP', 'PORTAL_UNAVAILABLE')),

  to_see text,  -- who they came to see (investor, delivery, visitor)

  checked_in_at  timestamptz NOT NULL DEFAULT now(),
  checked_in_by  uuid NOT NULL REFERENCES staff (id),
  checked_out_at timestamptz,
  -- NULL for AUTO_CLOSED (a visit nobody checked out, closed by policy).
  checked_out_by uuid REFERENCES staff (id),
  close_reason   text
    CONSTRAINT visit_close_reason_valid_check CHECK (close_reason IN ('NORMAL', 'NO_SHOW', 'AUTO_CLOSED')),

  created_at timestamptz NOT NULL DEFAULT now(),
  updated_at timestamptz NOT NULL DEFAULT now(),

  CONSTRAINT visit_identity_exactly_one_check
    CHECK ((portal_client_id IS NULL) <> (visitor_id IS NULL)),
  CONSTRAINT visit_client_name_matches_client_check
    CHECK ((portal_client_id IS NULL) = (client_name_logged IS NULL)),
  CONSTRAINT visit_matched_iff_client_check
    CHECK ((lookup_outcome = 'MATCHED') = (portal_client_id IS NOT NULL)),
  CONSTRAINT visit_close_reason_matches_checkout_check
    CHECK ((checked_out_at IS NULL) = (close_reason IS NULL)),
  CONSTRAINT visit_checkout_by_needs_checkout_check
    CHECK (checked_out_by IS NULL OR checked_out_at IS NOT NULL),
  CONSTRAINT visit_manual_close_needs_staff_check
    CHECK (close_reason IS NULL OR close_reason = 'AUTO_CLOSED' OR checked_out_by IS NOT NULL),
  CONSTRAINT visit_checkout_after_checkin_check
    CHECK (checked_out_at IS NULL OR checked_out_at >= checked_in_at),
  -- Only a Client type is ever matched against the portal.
  CONSTRAINT visit_matched_only_for_client_type_check
    CHECK (lookup_outcome <> 'MATCHED' OR visitor_type_code = 'CLIENT'),
  -- Targets for the composite foreign keys in 004 (enquiry) and 008 (case link),
  -- which make "a non-client never gets a case" and "an enquiry is never a
  -- client's" true in the database, not only in the application.
  CONSTRAINT visit_id_visitor_id_key UNIQUE (id, visitor_id),
  CONSTRAINT visit_id_portal_client_id_key UNIQUE (id, portal_client_id)
);

-- The Active Visits list.
CREATE INDEX visit_active_idx ON visit (checked_in_at) WHERE checked_out_at IS NULL;
CREATE INDEX visit_checked_in_idx ON visit (checked_in_at);
-- Visit frequency per person (GROUP BY the identity).
CREATE INDEX visit_client_idx ON visit (portal_client_id, checked_in_at)
  WHERE portal_client_id IS NOT NULL;
CREATE INDEX visit_visitor_idx ON visit (visitor_id, checked_in_at)
  WHERE visitor_id IS NOT NULL;

CREATE TRIGGER visit_touch_updated_at
  BEFORE UPDATE ON visit
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

-- The visit timeline, append-only. Check-in and check-out are NOT events: they
-- are columns of visit, and the timeline shows them as synthetic entries, so the
-- same fact is never written twice. payload carries ids only, never client data.
CREATE TABLE visit_event (
  id             uuid PRIMARY KEY,
  visit_id       uuid NOT NULL REFERENCES visit (id),
  kind           text NOT NULL
    CONSTRAINT visit_event_kind_valid_check CHECK (kind IN
      ('NOTE', 'EDITED', 'ENQUIRY_LOGGED', 'CASE_LINKED', 'HANDOVER_RECORDED')),
  occurred_at    timestamptz NOT NULL DEFAULT now(),
  actor_staff_id uuid NOT NULL REFERENCES staff (id),
  body           text,
  payload        jsonb,
  CONSTRAINT visit_event_note_needs_body_check
    CHECK (kind <> 'NOTE' OR (body IS NOT NULL AND btrim(body) <> ''))
);

CREATE INDEX visit_event_visit_idx ON visit_event (visit_id, occurred_at);

CREATE TRIGGER visit_event_no_row_change
  BEFORE UPDATE OR DELETE ON visit_event
  FOR EACH ROW EXECUTE PROCEDURE forbid_change();
CREATE TRIGGER visit_event_no_truncate
  BEFORE TRUNCATE ON visit_event
  FOR EACH STATEMENT EXECUTE PROCEDURE forbid_change();

COMMIT;
\echo '>>> applying 004_enquiries.sql'
-- 004 enquiries: what a NON-CLIENT raises at the desk (CLAUDE.md rule 3).
--
-- A non-client gets an ENQUIRY in CSS's own log, never a portal case. Two states
-- only, OPEN and CLOSED; no further workflow (owner's decision).
--
-- The composite foreign key (visit_id, visitor_id) -> visit (id, visitor_id) is
-- the point of this file: visitor_id is NOT NULL here, and a visit that belongs
-- to a portal client has visitor_id NULL, so it can never match. An enquiry on a
-- client's visit is rejected by the database.

BEGIN;

CREATE TABLE enquiry (
  id           uuid PRIMARY KEY,
  visit_id     uuid NOT NULL,
  visitor_id   uuid NOT NULL,
  topic_code   text NOT NULL REFERENCES enquiry_topic (code),
  summary      text NOT NULL
    CONSTRAINT enquiry_summary_not_blank_check CHECK (btrim(summary) <> ''),
  status       text NOT NULL DEFAULT 'OPEN'
    CONSTRAINT enquiry_status_valid_check CHECK (status IN ('OPEN', 'CLOSED')),
  assigned_to  uuid REFERENCES staff (id),
  opened_by    uuid NOT NULL REFERENCES staff (id),
  opened_at    timestamptz NOT NULL DEFAULT now(),
  closed_by    uuid REFERENCES staff (id),
  closed_at    timestamptz,
  outcome_note text,
  created_at   timestamptz NOT NULL DEFAULT now(),
  updated_at   timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT enquiry_visit_is_non_client_fkey
    FOREIGN KEY (visit_id, visitor_id) REFERENCES visit (id, visitor_id),
  CONSTRAINT enquiry_closed_at_matches_status_check
    CHECK ((status = 'CLOSED') = (closed_at IS NOT NULL)),
  CONSTRAINT enquiry_closed_by_matches_status_check
    CHECK ((status = 'CLOSED') = (closed_by IS NOT NULL)),
  CONSTRAINT enquiry_closed_after_opened_check
    CHECK (closed_at IS NULL OR closed_at >= opened_at)
);

CREATE INDEX enquiry_open_idx ON enquiry (opened_at) WHERE status = 'OPEN';
CREATE INDEX enquiry_visit_idx ON enquiry (visit_id);
CREATE INDEX enquiry_visitor_idx ON enquiry (visitor_id);

CREATE TRIGGER enquiry_touch_updated_at
  BEFORE UPDATE ON enquiry
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

COMMIT;
\echo '>>> applying 005_attendance.sql'
-- 005 staff attendance and leave, plus the settings they read.
--
-- Not in the PRD; this is screens 07 and 08. Present / late / absent / on leave,
-- shift durations and the week and month totals are DERIVED from these rows and
-- are never stored.
--
-- What attendance proves: that the person AUTHENTICATED at a registered device
-- (or from the office network). It cannot prove physical presence (a PIN can be
-- shoulder-surfed). The device and IP are recorded so the register can show them
-- and so two clock-ins from one device in quick succession can be flagged.

BEGIN;

CREATE TABLE attendance_record (
  id                   uuid PRIMARY KEY,
  staff_id             uuid NOT NULL REFERENCES staff (id),
  clock_in_at          timestamptz NOT NULL DEFAULT now(),
  clock_out_at         timestamptz,
  clock_in_device_id   uuid REFERENCES device (id),
  clock_out_device_id  uuid REFERENCES device (id),
  clock_in_ip          inet,
  clock_out_ip         inet,
  -- Set only when an admin entered or corrected the times for someone else. A
  -- correction must say why; the before/after goes to audit_log.
  entered_by           uuid REFERENCES staff (id),
  correction_reason    text,
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT attendance_clock_out_after_in_check
    CHECK (clock_out_at IS NULL OR clock_out_at >= clock_in_at),
  CONSTRAINT attendance_correction_reason_matches_entered_by_check
    CHECK ((entered_by IS NULL) = (correction_reason IS NULL)),
  CONSTRAINT attendance_correction_reason_not_blank_check
    CHECK (correction_reason IS NULL OR btrim(correction_reason) <> '')
);

-- One open shift per person. "At most one record per Lagos day" is an
-- application rule (checked in a transaction), not a constraint.
CREATE UNIQUE INDEX attendance_one_open_shift_key ON attendance_record (staff_id)
  WHERE clock_out_at IS NULL;
CREATE INDEX attendance_staff_idx ON attendance_record (staff_id, clock_in_at);
-- The register for a day: a range scan on clock_in_at between Lagos midnights.
CREATE INDEX attendance_clock_in_idx ON attendance_record (clock_in_at);

CREATE TRIGGER attendance_touch_updated_at
  BEFORE UPDATE ON attendance_record
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

-- Leave: dates and a kind, nothing more. Screen 08's ON LEAVE reads this.
-- Calendar days in Lagos, so `date`, not timestamptz. Overlapping leave for one
-- person is checked by the application (an exclusion constraint would need the
-- btree_gist extension, which these files avoid).
CREATE TABLE leave (
  id          uuid PRIMARY KEY,
  staff_id    uuid NOT NULL REFERENCES staff (id),
  starts_on   date NOT NULL,
  ends_on     date NOT NULL,
  kind_code   text NOT NULL REFERENCES leave_kind (code),
  approved_by uuid REFERENCES staff (id),
  note        text,
  created_by  uuid NOT NULL REFERENCES staff (id),
  created_at  timestamptz NOT NULL DEFAULT now(),
  updated_at  timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT leave_ends_on_or_after_starts_check CHECK (ends_on >= starts_on)
);

CREATE INDEX leave_staff_idx ON leave (staff_id, starts_on);
CREATE INDEX leave_range_idx ON leave (starts_on, ends_on);

CREATE TRIGGER leave_touch_updated_at
  BEFORE UPDATE ON leave
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

-- Small configuration the application reads. Dropdown lists are NOT here: they
-- are lookup tables with foreign keys.
--
-- A key is <domain>.<name>: exactly one dot, lower snake case on each side, and
-- the domain is the area of the app the setting governs (attendance, visits, ...).
CREATE TABLE setting (
  key        text PRIMARY KEY CONSTRAINT setting_key_format_check
             CHECK (key ~ '^[a-z][a-z0-9_]*\.[a-z][a-z0-9_]*$'),
  value      jsonb NOT NULL,
  updated_by uuid REFERENCES staff (id),
  updated_at timestamptz NOT NULL DEFAULT now()
);

CREATE TRIGGER setting_touch_updated_at
  BEFORE UPDATE ON setting
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

INSERT INTO setting (key, value) VALUES
  -- Office-local wall-clock time after which a clock-in is late. The design's
  -- rule is 09:15. Compared in Africa/Lagos.
  ('attendance.late_after_local', '"09:15"'),
  -- PLACEHOLDERS (07's targets: 40h a week, 160h a month), in minutes.
  ('attendance.weekly_target_minutes',  '2400'),
  ('attendance.monthly_target_minutes', '9600'),
  -- Office network egress addresses, for the clock-in network check. Empty = no
  -- IP check yet.
  ('attendance.office_ip_allowlist', '[]');

COMMIT;
\echo '>>> applying 006_audit_log.sql'
-- 006 audit log: every create / update / delete, with who and before / after.
--
-- Append-only (trigger here; the application's database role must also have no
-- UPDATE, DELETE or TRUNCATE grant). The PRD's 3-year retention means a purge,
-- and an append-only table needs a deliberate privileged path for it. That path
-- is not built here; decide it before the first purge is due.
--
-- before / after carry fields from an ALLOW-LIST kept in the application. Never
-- put portal client data in them (no email, balances, fee status, case text).

BEGIN;

CREATE TABLE audit_log (
  id             bigint GENERATED ALWAYS AS IDENTITY PRIMARY KEY,
  at             timestamptz NOT NULL DEFAULT now(),
  -- NULL = the system itself (for example an auto-close).
  actor_staff_id uuid REFERENCES staff (id),
  entity         text NOT NULL
    CONSTRAINT audit_log_entity_not_blank_check CHECK (btrim(entity) <> ''),
  entity_id      text NOT NULL,
  action         text NOT NULL
    CONSTRAINT audit_log_action_valid_check CHECK (action IN ('CREATE', 'UPDATE', 'DELETE')),
  before         jsonb,
  after          jsonb,
  CONSTRAINT audit_log_before_required_unless_create_check
    CHECK (action = 'CREATE' OR before IS NOT NULL),
  CONSTRAINT audit_log_after_required_unless_delete_check
    CHECK (action = 'DELETE' OR after IS NOT NULL)
);

CREATE INDEX audit_log_entity_idx ON audit_log (entity, entity_id, at);
CREATE INDEX audit_log_at_idx ON audit_log (at);
CREATE INDEX audit_log_actor_idx ON audit_log (actor_staff_id, at);

CREATE TRIGGER audit_log_no_row_change
  BEFORE UPDATE OR DELETE ON audit_log
  FOR EACH ROW EXECUTE PROCEDURE forbid_change();
CREATE TRIGGER audit_log_no_truncate
  BEFORE TRUNCATE ON audit_log
  FOR EACH STATEMENT EXECUTE PROCEDURE forbid_change();

COMMIT;
\echo '>>> applying 007_handovers.sql'
-- 007 document handovers: the physical record that Legal gave a visitor a
-- document (PRD 6.2, FR-3.1 to FR-3.5). Not used by any built screen yet.
--
-- THE GATE IS THE PORTAL'S. CSS has no override and no PIN (owner's decision,
-- see CLAUDE.md). `gate_answer` records what the portal's release-check told the
-- desk at the moment of handover. It is an audit fact, not a mirror of portal
-- data, and it is the only portal answer CSS stores.
--
--   CHECKED_ALLOWED  release-check answered, and allowed it.
--   CHECKED_BLOCKED  release-check answered, and refused it.
--   GATE_OFF         the gate was off (409 GATE_NOT_ACTIVE): "unknown, do not release".
--   UNAVAILABLE      the check could not be made (network, 429, 503).
--   NOT_GATED        the document is outside the gate (an unattached document).
--
-- The application offers "record a handover" ONLY on CHECKED_ALLOWED or
-- NOT_GATED. The other three values exist because a handover that happened
-- anyway is a fact the audit trail must not lose: refusing to record a release
-- does not undo it. A row carrying one of them is reportable.
--
-- Handover rows are append-only. A mistake is answered by a new row, not an edit.

BEGIN;

-- The portal's document vocabulary: the six slots, then OTHER (an unattached
-- document's seventh type). Labels are the portal's own (portal.ts
-- DOCUMENT_LABELS). The PRD's starter list used different names; the portal's
-- are authoritative. A new type is an INSERT.
CREATE TABLE document_type (
  code       text PRIMARY KEY CONSTRAINT document_type_code_format_check CHECK (code ~ '^[A-Z][A-Z0-9_]*$'),
  label      text NOT NULL,
  is_active  boolean NOT NULL DEFAULT true,
  sort_order integer NOT NULL DEFAULT 0,
  created_at timestamptz NOT NULL DEFAULT now()
);

INSERT INTO document_type (code, label, sort_order) VALUES
  ('DEED_OF_ASSIGNMENT',       'Deed of Assignment',        1),
  ('SURVEY_PLAN',              'Provisional Survey Plan',   2),
  ('RECEIPT',                  'Receipt of Payment',        3),
  ('CONTRACT_OF_SALE',         'Purchase Agreement',        4),
  ('ACKNOWLEDGMENT_LETTER',    'Initial Allocation Letter', 5),
  ('CERTIFICATE_OF_OCCUPANCY', 'C of O Copy',               6),
  ('OTHER',                    'Other',                     7);

CREATE TABLE handover (
  id                 uuid PRIMARY KEY,
  visit_id           uuid NOT NULL REFERENCES visit (id),
  released_by        uuid NOT NULL REFERENCES staff (id),
  released_at        timestamptz NOT NULL DEFAULT now(),
  -- The portal's purchase id the documents belong to, opaque. NULL when the
  -- handover is not tied to one purchase.
  portal_purchase_id text,
  gate_answer        text NOT NULL
    CONSTRAINT handover_gate_answer_valid_check CHECK (gate_answer IN
      ('CHECKED_ALLOWED', 'CHECKED_BLOCKED', 'GATE_OFF', 'UNAVAILABLE', 'NOT_GATED')),
  -- The requestId of the portal call that gave the answer, so the portal's owner
  -- can find it. NULL only when no call was made or none returned one.
  gate_request_id    text,
  note               text,
  created_at         timestamptz NOT NULL DEFAULT now()
);

CREATE INDEX handover_visit_idx ON handover (visit_id);
CREATE INDEX handover_released_idx ON handover (released_at);

CREATE TABLE handover_item (
  handover_id        uuid NOT NULL REFERENCES handover (id),
  document_type_code text NOT NULL REFERENCES document_type (code),
  quantity           integer NOT NULL
    CONSTRAINT handover_item_quantity_positive_check CHECK (quantity > 0),
  PRIMARY KEY (handover_id, document_type_code)
);

CREATE TRIGGER handover_no_row_change
  BEFORE UPDATE OR DELETE ON handover
  FOR EACH ROW EXECUTE PROCEDURE forbid_change();
CREATE TRIGGER handover_no_truncate
  BEFORE TRUNCATE ON handover
  FOR EACH STATEMENT EXECUTE PROCEDURE forbid_change();

CREATE TRIGGER handover_item_no_row_change
  BEFORE UPDATE OR DELETE ON handover_item
  FOR EACH ROW EXECUTE PROCEDURE forbid_change();
CREATE TRIGGER handover_item_no_truncate
  BEFORE TRUNCATE ON handover_item
  FOR EACH STATEMENT EXECUTE PROCEDURE forbid_change();

COMMIT;
\echo '>>> applying 008_case_links.sql'
-- 008 case links: ties a CSS visit to a PORTAL case, so the same complaint is not
-- raised twice. INERT until the portal's case endpoints exist (none is built).
-- Kept in its own file so it can be dropped or changed without touching the rest.
--
-- CSS stores NO complaint text, status, age or resolution (rule 2: the portal
-- owns them). Only the link and the request that created it. Consequence: if
-- the portal call fails, what the desk typed lives only in the browser.
--
-- Both tables use composite foreign keys to visit (id, portal_client_id), whose
-- column is NULL on a non-client's visit. A non-client therefore cannot have a
-- case link or a case request: the database refuses it (rule 3).

BEGIN;

-- A case CSS knows about for a visit.
--  RAISED_HERE  this visit created it (through the portal's create endpoint).
--  DISCUSSED    an existing case that came up at this visit.
CREATE TABLE visit_case_link (
  id               uuid PRIMARY KEY,
  visit_id         uuid NOT NULL,
  portal_client_id uuid NOT NULL,
  portal_case_id   text NOT NULL
    CONSTRAINT visit_case_link_case_id_not_blank_check CHECK (btrim(portal_case_id) <> ''),
  kind             text NOT NULL
    CONSTRAINT visit_case_link_kind_valid_check CHECK (kind IN ('RAISED_HERE', 'DISCUSSED')),
  linked_by        uuid NOT NULL REFERENCES staff (id),
  linked_at        timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT visit_case_link_visit_is_client_fkey
    FOREIGN KEY (visit_id, portal_client_id) REFERENCES visit (id, portal_client_id),
  CONSTRAINT visit_case_link_visit_case_key UNIQUE (visit_id, portal_case_id)
);

CREATE INDEX visit_case_link_case_idx ON visit_case_link (portal_case_id);
CREATE INDEX visit_case_link_client_idx ON visit_case_link (portal_client_id);

-- An attempt to create a case. `id` IS the idempotency key: the application
-- generates it before calling the portal and sends it with the create request
-- (the portal must be asked to accept it; see CLAUDE.md). A retry after a
-- timeout reuses the same row and the same key.
--
--  PENDING    sent, outcome not known (including after a timeout). NOT a failure.
--  CONFIRMED  the portal answered with the case id.
--  FAILED     the portal definitely did not create it.
CREATE TABLE case_request (
  id                 uuid PRIMARY KEY,
  visit_id           uuid NOT NULL,
  portal_client_id   uuid NOT NULL,
  -- The portal's dispute type code (its vocabulary, not ours: no foreign key).
  -- REALTOR_CONDUCT is record-only on the portal and can never be read back by a
  -- CSS key, so CSS must never raise one.
  type_code          text NOT NULL,
  portal_purchase_id text,
  state              text NOT NULL DEFAULT 'PENDING'
    CONSTRAINT case_request_state_valid_check CHECK (state IN ('PENDING', 'CONFIRMED', 'FAILED')),
  portal_case_id     text,
  requested_by       uuid NOT NULL REFERENCES staff (id),
  requested_at       timestamptz NOT NULL DEFAULT now(),
  settled_at         timestamptz,
  updated_at         timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT case_request_visit_is_client_fkey
    FOREIGN KEY (visit_id, portal_client_id) REFERENCES visit (id, portal_client_id),
  CONSTRAINT case_request_type_code_format_check
    CHECK (type_code ~ '^[A-Z][A-Z0-9_]*$'),
  CONSTRAINT case_request_not_realtor_conduct_check
    CHECK (type_code <> 'REALTOR_CONDUCT'),
  CONSTRAINT case_request_case_id_matches_confirmed_check
    CHECK ((state = 'CONFIRMED') = (portal_case_id IS NOT NULL)),
  CONSTRAINT case_request_settled_at_matches_pending_check
    CHECK ((state = 'PENDING') = (settled_at IS NULL))
);

-- The double-submit guard: one live request per visit, type and purchase.
CREATE UNIQUE INDEX case_request_live_key
  ON case_request (visit_id, type_code, coalesce(portal_purchase_id, ''))
  WHERE state IN ('PENDING', 'CONFIRMED');
CREATE INDEX case_request_pending_idx ON case_request (requested_at) WHERE state = 'PENDING';

CREATE TRIGGER case_request_touch_updated_at
  BEFORE UPDATE ON case_request
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

COMMIT;
\echo '>>> applying 009_attendance_device.sql'
-- 009 attendance device: record WHERE a clock-in and a clock-out came from, and
-- add the switch that can later forbid clocking in from a personal device.
--
-- Context. There is no front-desk computer yet; staff log in from their own
-- phones, so a clock-in can happen from anywhere. That is NOT blocked, because
-- the hardware does not exist. It is RECORDED and made visible (screen 08 must
-- mark a clock-in made from a PERSONAL device), and the setting seeded below is
-- the switch for tightening it later. This file only ADDS to attendance_record
-- (ALTER TABLE ... ADD); it does not rewrite anything.
--
-- The device ids (clock_in_device_id, clock_out_device_id) already exist from 005.
-- This adds the KIND of each device, as a SNAPSHOT.
--
-- WHY A SNAPSHOT AND NOT A LIVE LOOKUP. device.kind can change: a device can be
-- relabelled from PERSONAL to DESK later (or the reverse). An attendance record
-- from before the change must keep saying what the device WAS when the person
-- clocked in, or the register would rewrite its own history and a PERSONAL
-- clock-in would quietly turn into a DESK one. This is the same reason
-- visit.client_name_logged exists: a log records what was true at the time, not
-- what the other table says now. The application writes the kind when it writes
-- the record; the database can only check that it is well formed, not that it
-- matches device.kind at that moment.
--
-- The kind columns are NULL on a row with no device, so there is nothing to
-- backfill on a new schema. No attendance row has ever been written (the
-- application does not exist yet). If rows with a device but no kind ever
-- existed, the constraints below would reject this migration rather than guess.

BEGIN;

ALTER TABLE attendance_record
  ADD COLUMN clock_in_device_kind text
    CONSTRAINT attendance_clock_in_device_kind_valid_check
    CHECK (clock_in_device_kind IN ('DESK', 'PERSONAL')),
  ADD COLUMN clock_out_device_kind text
    CONSTRAINT attendance_clock_out_device_kind_valid_check
    CHECK (clock_out_device_kind IN ('DESK', 'PERSONAL'));

-- A device and its kind travel together: both set or both null, never one.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_clock_in_device_pair_check
    CHECK ((clock_in_device_id IS NULL) = (clock_in_device_kind IS NULL)),
  ADD CONSTRAINT attendance_clock_out_device_pair_check
    CHECK ((clock_out_device_id IS NULL) = (clock_out_device_kind IS NULL));

-- A clock-out device can only exist on a record that has been clocked out.
-- (The kind follows from the pair check above.) The reverse is allowed: a
-- clock-out time with no device is an admin-entered or corrected record.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_clock_out_device_needs_clock_out_check
    CHECK (clock_out_device_id IS NULL OR clock_out_at IS NOT NULL);

-- A real clock-in always has a device; an admin-entered row never does. So a row
-- with NO clock-in device must be a manual entry, which 005 already forces to
-- carry a correction_reason (attendance_correction_reason_matches_entered_by_check
-- ties the reason to entered_by). This is what stops a missing device from
-- looking like a legitimate clock-in.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_no_device_needs_correction_reason_check
    CHECK (clock_in_device_id IS NOT NULL OR correction_reason IS NOT NULL);

-- The tightening switch. false = clocking in from any device is allowed (and
-- recorded, with its kind). When the reception computer is bought and registered
-- as a DESK device, setting this row's value to true makes the application refuse
-- a clock-in from a PERSONAL device: an UPDATE of this one row, with no code
-- change and no migration. NOTHING READS IT YET; it exists so the switch is
-- already in place.
INSERT INTO setting (key, value) VALUES
  ('attendance.clock_in_requires_desk_device', 'false');

COMMIT;
\echo '>>> applying 010_roster_movements_backdating.sql'
-- 010 roster people, the movement book, and back-dated attendance.
--
-- WHY. Attendance does not work the way 005 and 009 assumed. Staff do not clock
-- themselves in: they sign a paper book at reception and the front desk copies it
-- into CSS in a batch, clocking people out one at a time through the day. Only the
-- front desk (one or two people) and the owner ever sign in. The people whose
-- attendance is recorded have no login, never will, and must still be stored. A
-- second paper book, the movement book, records every time one of them leaves the
-- premises and comes back. Any earlier day can be entered or corrected. See
-- CLAUDE.md, "ATTENDANCE: HOW IT REALLY WORKS".
--
-- This is the first APPEND-ONLY migration: 001 to 009 are not touched. It runs on
-- a database that already holds 001 to 009 (the cPanel server) AND on a fresh one,
-- in order. Nothing has ever written an attendance row, which the NOT NULL in
-- section 2 relies on: it would fail loudly, not guess, if a row existed.

BEGIN;

-- ---------------------------------------------------------------------------
-- 1. A person who never signs in must be storable in `staff`.
--
-- `staff` now holds two kinds of person. A LOGIN account has a password hash and an
-- email. A ROSTER person has neither (usually), may have no department yet (a
-- required department would block quick entry; screen 08 groups them under
-- "unassigned"), and is only ever the subject of attendance or the approver named
-- on a movement. Whether a row can sign in is decided by password_hash IS NOT NULL
-- and nothing else; the application refuses a NULL hash (authCore.ts).
--
-- NULLs and the checks already on the table:
--  * staff_email_format_check is  email = btrim(email) AND position('@' in email) > 1.
--    A CHECK passes when its expression is NULL (only FALSE fails), and with a NULL
--    email the whole expression is NULL, so a roster person passes. A NON-NULL email
--    is still fully checked, so '' or ' a@b' or 'ab' is still refused.
--  * staff_email_lower_key is a unique index on lower(email). A unique index treats
--    NULLs as distinct from each other, so any number of roster people can have no
--    email; two people with the SAME non-null email are still refused.
--  * staff_department_not_blank_check is  btrim(department) <> ''. NULL passes, but
--    an empty or all-space department is still refused: "none" is NULL, never ''.
ALTER TABLE staff
  ALTER COLUMN email         DROP NOT NULL,
  ALTER COLUMN department    DROP NOT NULL,
  ALTER COLUMN password_hash DROP NOT NULL;

-- You cannot sign in without an identifier: a password needs an email to go with it.
ALTER TABLE staff
  ADD CONSTRAINT staff_password_needs_email_check
    CHECK (password_hash IS NULL OR email IS NOT NULL);

-- ---------------------------------------------------------------------------
-- 2. attendance_record: the front desk enters everything.
--
-- Two constraints from 005 and 009 assumed self-service and now forbid the normal
-- case, so they are dropped (not edited; 005 and 009 stay as they ran):
--   attendance_correction_reason_matches_entered_by_check
--     said: entered_by is set exactly when correction_reason is. But now EVERY
--     record has entered_by (the front desk typed it), and only a CORRECTION of an
--     existing record has a correction_reason.
--   attendance_no_device_needs_correction_reason_check
--     said: no clock-in device means a manual entry, which must carry a reason. But
--     there is no registered desk device yet (the table is empty), so every entry
--     has no device, and a reason on every row would be noise.
-- What still guards correction_reason: attendance_correction_reason_not_blank_check
-- (005), so a reason, when present, is never blank. That a correction CARRIES a
-- reason is an application rule (the database cannot tell an UPDATE from a first
-- write in a CHECK); the before and after of every correction go to audit_log.
ALTER TABLE attendance_record
  DROP CONSTRAINT attendance_correction_reason_matches_entered_by_check;
ALTER TABLE attendance_record
  DROP CONSTRAINT attendance_no_device_needs_correction_reason_check;

-- Every record says WHO ENTERED IT: screen 08 shows it, because one person typing
-- everyone else's attendance is the thing that must be visible. (The device columns
-- from 009 stay, now meaning "the machine the ENTRY was made on".)
ALTER TABLE attendance_record
  ALTER COLUMN entered_by SET NOT NULL;

-- A record CREATED for an earlier day is a different event from a correction of an
-- existing record, so it has its own reason, not blank when present.
--
-- NOT ENFORCED BY THE DATABASE: "a back-dated record must carry a reason". Back-dated
-- means the Lagos day of clock_in_at is before the day the row was written, and that
-- needs now(). now() is not immutable and cannot appear in a CHECK constraint.
-- (created_at is no help: it is itself now().) So the APPLICATION must set
-- backdate_reason whenever it creates a record for a Lagos day before today
-- (lagosDateOf, lagosTime.ts). The database only refuses a blank one. Do not assume
-- a record without a backdate_reason was written on the day it describes.
ALTER TABLE attendance_record
  ADD COLUMN backdate_reason text
    CONSTRAINT attendance_backdate_reason_not_blank_check
    CHECK (backdate_reason IS NULL OR btrim(backdate_reason) <> '');

-- ---------------------------------------------------------------------------
-- 3. movement: leaving the premises during the day, and coming back.
--
-- A movement belongs to an attendance_record, NOT to a person: it only makes sense
-- for someone recorded as in that day, and NOT NULL plus the foreign key make the
-- database refuse any other. An open movement (returned_at IS NULL) means the
-- person is out NOW.
CREATE TABLE movement (
  id                   uuid PRIMARY KEY,
  attendance_record_id uuid NOT NULL REFERENCES attendance_record (id),
  left_at              timestamptz NOT NULL DEFAULT now(),
  returned_at          timestamptz,
  destination          text NOT NULL
    CONSTRAINT movement_destination_not_blank_check CHECK (btrim(destination) <> ''),
  purpose              text NOT NULL
    CONSTRAINT movement_purpose_not_blank_check CHECK (btrim(purpose) <> ''),
  -- A staff row, so whoever approves a movement must exist in the roster. Whether the
  -- approver must be a manager, and may not be the person leaving, is an application
  -- rule: the approver's role is in staff_role, and "the person leaving" is reached
  -- through attendance_record, neither of which a CHECK can see.
  approved_by          uuid NOT NULL REFERENCES staff (id),
  -- The front-desk person who wrote it down (named entered_by, like attendance_record).
  entered_by           uuid NOT NULL REFERENCES staff (id),
  -- The machine the entry was made on, recorded as attendance_record does it (009):
  -- the id plus a SNAPSHOT of the kind, so relabelling a device later never rewrites
  -- history. Both set or both null.
  entered_device_id    uuid REFERENCES device (id),
  entered_device_kind  text
    CONSTRAINT movement_entered_device_kind_valid_check CHECK (entered_device_kind IN ('DESK', 'PERSONAL')),
  created_at           timestamptz NOT NULL DEFAULT now(),
  updated_at           timestamptz NOT NULL DEFAULT now(),
  CONSTRAINT movement_returned_after_left_check
    CHECK (returned_at IS NULL OR returned_at >= left_at),
  CONSTRAINT movement_entered_device_pair_check
    CHECK ((entered_device_id IS NULL) = (entered_device_kind IS NULL))
);

-- NOT ENFORCED BY THE DATABASE: "a movement lies inside its shift", that is
--   left_at >= clock_in_at of its record, and, once the record is clocked out,
--   returned_at <= clock_out_at, and a record cannot be clocked out while one of its
--   movements is still open.
-- A CHECK can only see its own row, and these compare columns of two tables. A
-- trigger could, but it would have to fire on BOTH tables (a correction that moves
-- clock_in_at later would orphan a movement that was legal when written), it could
-- only raise an error with no message a front-desk person can act on, and this
-- schema keeps triggers for the append-only guards and touch_updated_at. So the
-- APPLICATION checks it, in the same transaction as the write and for BOTH writes
-- (recording a movement, and correcting or closing the shift), and
-- dbConstraints.ts has no entry for it because the database never reports it. Do not
-- assume a row here is inside its shift just because it was accepted.

-- One open movement per record: a person cannot be out twice at the same time. This
-- partial unique index is also THE index for the question asked all day, "who is out
-- right now?": it holds exactly the open movements and nothing else.
CREATE UNIQUE INDEX movement_one_open_key ON movement (attendance_record_id)
  WHERE returned_at IS NULL;
-- A person's movements for a day, in order (the record carries the day).
CREATE INDEX movement_record_idx ON movement (attendance_record_id, left_at);

CREATE TRIGGER movement_touch_updated_at
  BEFORE UPDATE ON movement
  FOR EACH ROW EXECUTE PROCEDURE touch_updated_at();

COMMIT;
\echo '>>> applying 011_entered_by_per_event.sql'
-- 011 who typed each EVENT, not just each record.
--
-- WHY. 010 gave attendance_record one entered_by. But a record is two events, the
-- arrival and the departure, and with one or two front-desk people they are often
-- typed by different people (one copies the morning's arrivals from the paper book,
-- the other clocks people out through the day). "Who typed this" is the
-- accountability mechanism for the whole feature, so it must say which event. The
-- same is true of a movement: whoever records the return may not be whoever recorded
-- the departure.
--
-- Nothing outside this repository reads these columns and the server holds no
-- attendance data, so the rename is safe and no data needs carrying across.
--
-- Append-only: 001 to 010 are not touched. The server receives 010 and 011 together.

BEGIN;

-- 1. The arrival. entered_by now means "who typed the ARRIVAL", and the honest name
--    prevents permanent confusion. A column rename keeps its NOT NULL (from 010) and
--    its foreign key, but PostgreSQL does not rename the foreign key's NAME, and a
--    constraint name is part of the application's contract (dbConstraints.ts), so it
--    is renamed to match.
ALTER TABLE attendance_record
  RENAME COLUMN entered_by TO clock_in_entered_by;
ALTER TABLE attendance_record
  RENAME CONSTRAINT attendance_record_entered_by_fkey TO attendance_clock_in_entered_by_fkey;

-- 2. The departure: who typed the clock-out. Present exactly when the clock-out time
--    is: a departure with nobody to answer for it cannot be stored, and neither can a
--    name against a departure that has not happened.
ALTER TABLE attendance_record
  ADD COLUMN clock_out_entered_by uuid;
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_clock_out_entered_by_fkey
    FOREIGN KEY (clock_out_entered_by) REFERENCES staff (id);
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_clock_out_entered_by_matches_check
    CHECK ((clock_out_at IS NULL) = (clock_out_entered_by IS NULL));

-- 3. A movement's return: who typed it, present exactly when returned_at is. (The
--    departure's author is movement.entered_by, from 010.)
ALTER TABLE movement
  ADD COLUMN returned_recorded_by uuid;
ALTER TABLE movement
  ADD CONSTRAINT movement_returned_recorded_by_fkey
    FOREIGN KEY (returned_recorded_by) REFERENCES staff (id);
ALTER TABLE movement
  ADD CONSTRAINT movement_returned_recorded_by_matches_check
    CHECK ((returned_at IS NULL) = (returned_recorded_by IS NULL));

COMMIT;
\echo '>>> applying 012_movement_entered_by_names.sql'
-- 012 one naming pattern for "who typed it": <event>_entered_by.
--
-- attendance_record already follows it (clock_in_entered_by, clock_out_entered_by,
-- from 010 and 011). movement did not: 010 named the author of the departure
-- entered_by, and 011 named the author of the return returned_recorded_by. Both
-- now say which EVENT they belong to, in the same shape.
--
--   movement.entered_by           ->  left_entered_by       (who typed the departure)
--   movement.returned_recorded_by ->  returned_entered_by   (who typed the return)
--
-- This is a new migration and not an edit to 010 or 011, even though the server has
-- neither yet: both are applied to the local database that holds the owner's login,
-- which cannot be rebuilt, and a migration file must describe a schema that exists.
--
-- As in 011, a column rename leaves its foreign key's and check's NAMES alone, and a
-- constraint name is part of the application's contract (dbConstraints.ts), so each
-- is renamed to match. Nothing else changes: no column, type, nullability or rule.
-- (movement.entered_device_id and entered_device_kind keep their names: they record
-- the machine the departure was entered on, as attendance_record's device columns do.)

BEGIN;

ALTER TABLE movement RENAME COLUMN entered_by TO left_entered_by;
ALTER TABLE movement RENAME CONSTRAINT movement_entered_by_fkey TO movement_left_entered_by_fkey;

ALTER TABLE movement RENAME COLUMN returned_recorded_by TO returned_entered_by;
ALTER TABLE movement RENAME CONSTRAINT movement_returned_recorded_by_fkey TO movement_returned_entered_by_fkey;
ALTER TABLE movement RENAME CONSTRAINT movement_returned_recorded_by_matches_check TO movement_returned_entered_by_matches_check;

COMMIT;
\echo '>>> applying 013_signout_missing.sql'
-- 013 a shift that was never signed out.
--
-- WHY. The paper book will have people who went home without signing out. Until now
-- a record had two states: OPEN (no clock-out: still here) and CLOSED (a clock-out
-- time). A person may have only one open shift, so a forgotten sign-out could never
-- be put right: it stayed open for ever and blocked that person's next arrival.
--
-- A record now has THREE states:
--   still here               clock_out_at IS NULL     signout_missing_at IS NULL
--   left at a time           clock_out_at IS NOT NULL signout_missing_at IS NULL
--   NEVER SIGNED OUT         clock_out_at IS NULL     signout_missing_at IS NOT NULL
-- The third is CLOSED but has no time. It is a fact about the BOOK ("no sign-out was
-- written"), not about the person ("left"), and it is what the front desk marks, as
-- an explicit act, at the end of the day. It records WHEN it was marked and BY WHOM.
--
-- THE HOURS OF SUCH A SHIFT ARE UNKNOWN. They must never be treated as zero hours,
-- and never guessed: not to the end of the day, not to a usual finishing time, not to
-- the last movement. A total, a week or a timesheet that includes one must say it
-- includes a shift with unknown hours, or leave it out and say so. There is no column
-- for an estimate, on purpose.

BEGIN;

ALTER TABLE attendance_record
  ADD COLUMN signout_missing_at timestamptz,
  ADD COLUMN signout_missing_by uuid;

-- Both set or both null: a marking always says who made it.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_signout_missing_by_fkey
    FOREIGN KEY (signout_missing_by) REFERENCES staff (id);
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_signout_missing_pair_check
    CHECK ((signout_missing_at IS NULL) = (signout_missing_by IS NULL));

-- "Never signed out" and "left at a time" are different answers to the same
-- question, so a record cannot be both.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_signout_missing_no_clock_out_check
    CHECK (signout_missing_at IS NULL OR clock_out_at IS NULL);

-- One OPEN shift per person, as before. A record that was never signed out is
-- closed, so it is excluded: it must not stop that person arriving the next day.
-- The index is rebuilt under the same name (an index, not a constraint, so there is
-- no DROP/ADD CONSTRAINT of one name here).
DROP INDEX attendance_one_open_shift_key;
CREATE UNIQUE INDEX attendance_one_open_shift_key ON attendance_record (staff_id)
  WHERE clock_out_at IS NULL AND signout_missing_at IS NULL;

COMMIT;
\echo '>>> applying 014_corrections.sql'
-- 014 corrections: who changed a record, when, and removing a record entered for the
-- wrong person.
--
-- WHY. The front desk will type 09:30 where the book says 08:30. A mistake that cannot
-- be fixed makes her keep a second paper list, and then this system is decoration. A
-- record can now be CORRECTED (a time changed, a clock-out undone, a never-signed-out
-- mark undone) or REMOVED (entered for the wrong person), always with a reason.
--
-- The FULL history of every correction (before and after) is in audit_log. These
-- columns exist only so that a list can show AT A GLANCE that a record was changed,
-- by whom, when and why, without going to the audit log. They always describe the
-- LATEST correction; earlier ones are in audit_log.
--
-- correction_reason already exists (005); it was always meant for changing an existing
-- record. It now travels with the other two: all three present or none.
--
-- REMOVED IS A VOID, NOT A DELETE. A removed record keeps its row and gets voided_at.
--  * A deleted row cannot be audited: audit_log refers to it by id, and the id would
--    point at nothing. A voided row stays, with its reason and who removed it.
--  * Other rows point at a record (movement.attendance_record_id); a delete would have
--    to cascade or fail.
--  * Staff, and everything that points at them, are never deleted in this system.
-- A voided row would clutter every list, so EVERYTHING that lists or counts records
-- leaves it out (the board, "one record per person per day", the open-shift index
-- below), and it appears only in a "Removed records" list. The application must apply
-- the same rule in any query of its own: a record with voided_at set does not exist for
-- today's board, for hours, or for the one-record-a-day check.

BEGIN;

ALTER TABLE attendance_record
  ADD COLUMN corrected_at timestamptz,
  ADD COLUMN corrected_by uuid,
  ADD COLUMN voided_at timestamptz;

ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_corrected_by_fkey
    FOREIGN KEY (corrected_by) REFERENCES staff (id);

-- When and by whom come together: a correction always says who made it.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_corrected_pair_check
    CHECK ((corrected_at IS NULL) = (corrected_by IS NULL));

-- And with the reason: a reason without them, or them without a reason, is refused.
-- (005's attendance_correction_reason_not_blank_check still refuses a blank reason.)
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_corrected_matches_reason_check
    CHECK ((correction_reason IS NULL) = (corrected_at IS NULL));

-- A removal is a correction: it carries the reason, the person and the time.
ALTER TABLE attendance_record
  ADD CONSTRAINT attendance_voided_needs_correction_check
    CHECK (voided_at IS NULL OR corrected_at IS NOT NULL);

-- One OPEN shift per person, as before, and a record that was never signed out is
-- closed (013). A REMOVED record is not a shift at all, so it must not block that
-- person (it is usually the wrong person's, and the right one is about to be entered).
-- Rebuilt under the same name.
DROP INDEX attendance_one_open_shift_key;
CREATE UNIQUE INDEX attendance_one_open_shift_key ON attendance_record (staff_id)
  WHERE clock_out_at IS NULL AND signout_missing_at IS NULL AND voided_at IS NULL;

COMMIT;
\echo '>>> applying 015_movement_corrections.sql'
-- 015 movements can be wrong too: corrections and removal.
--
-- The lesson from attendance (014) was that no way to correct is a blocker: she will
-- type 11:40 where the book says 10:40, or the wrong destination, or the wrong approver,
-- and a mistake that cannot be fixed makes her keep a second paper list. So movements get
-- the same columns attendance_record has, BEFORE the screens exist rather than after.
--
-- The FULL history of every correction (before and after) is in audit_log. These columns
-- are only so a list can show AT A GLANCE that a movement was changed, by whom, when and
-- why, and they always describe the LATEST correction. correction_reason, corrected_at
-- and corrected_by come together or not at all, exactly as on attendance_record.
--
-- REMOVED IS A VOID, NOT A DELETE (same reasoning as 014): the row stays, with its reason
-- and who removed it, so audit_log still points at something. A voided movement COUNTS
-- FOR NOTHING: it is not "out right now", it is in no total, and it does not stop the
-- same person leaving again. The index below excludes it; the application must exclude it
-- from every query of its own (a movement with voided_at set does not exist for the
-- board, for "who is out", for movements-inside-the-shift checks, or for any count).

BEGIN;

ALTER TABLE movement
  ADD COLUMN correction_reason text,
  ADD COLUMN corrected_at timestamptz,
  ADD COLUMN corrected_by uuid,
  ADD COLUMN voided_at timestamptz;

ALTER TABLE movement
  ADD CONSTRAINT movement_corrected_by_fkey
    FOREIGN KEY (corrected_by) REFERENCES staff (id);

-- A reason, when present, is never blank (as attendance_correction_reason_not_blank_check).
ALTER TABLE movement
  ADD CONSTRAINT movement_correction_reason_not_blank_check
    CHECK (correction_reason IS NULL OR btrim(correction_reason) <> '');

-- When and by whom come together: a correction always says who made it.
ALTER TABLE movement
  ADD CONSTRAINT movement_corrected_pair_check
    CHECK ((corrected_at IS NULL) = (corrected_by IS NULL));

-- And with the reason: a reason without them, or them without a reason, is refused.
ALTER TABLE movement
  ADD CONSTRAINT movement_corrected_matches_reason_check
    CHECK ((correction_reason IS NULL) = (corrected_at IS NULL));

-- A removal is a correction: it carries the reason, the person and the time.
ALTER TABLE movement
  ADD CONSTRAINT movement_voided_needs_correction_check
    CHECK (voided_at IS NULL OR corrected_at IS NOT NULL);

-- One OPEN movement per record, as before (a person cannot be out twice at once). A
-- REMOVED movement is not a movement at all, so it must not keep the person "out": the
-- index is rebuilt under the same name to exclude it. It is still THE index for the
-- question asked all day, "who is out right now?".
DROP INDEX movement_one_open_key;
CREATE UNIQUE INDEX movement_one_open_key ON movement (attendance_record_id)
  WHERE returned_at IS NULL AND voided_at IS NULL;

COMMIT;
\echo '>>> applying 016_late_threshold_snapshot.sql'
-- 016 the late threshold belongs to the record.
--
-- WHY. "Late" is a clock-in after attendance.late_after_local (a Lagos wall-clock time,
-- "09:15"). Until now the register judged EVERY record, of any date, by whatever that setting
-- says NOW. The setting exists to be changed, so changing it would silently re-judge every
-- past period, and the register is the document someone is judged by. Nobody re-checks a
-- number on a report.
--
-- So each record carries a SNAPSHOT of the threshold that applied when it was entered, and
-- lateness is judged from the snapshot everywhere (the register, any total; the board does
-- not judge lateness). THE SAME PATTERN AS visit.client_name_logged (003: the name as logged
-- at the desk, never refreshed from the portal) and attendance_record.clock_in_device_kind
-- (009: the device kind at the time of entry, so relabelling a device never rewrites
-- history): a value that can change later is COPIED onto the row when the row is written,
-- because the row records what was true then. It is never refreshed.
--
-- WHAT A CORRECTION DOES TO IT: NOTHING. Correcting a time in, a time out, reopening,
-- unmarking, removing or restoring never moves the snapshot. The rule that applied on the day
-- still applied on the day; a correction fixes what was TYPED, not which rule was in force.
-- (If the snapshot followed the setting at correction time, correcting a typo in March under
-- a rule changed in April would quietly re-judge a March arrival: exactly the problem this
-- migration exists to stop.)
--
-- A BACK-DATED record (entered on a later day than the one it describes) takes the setting
-- at the time of ENTRY. Setting history is not kept, so the rule on the day itself cannot be
-- known; when the setting has not changed in between, they are the same.
--
-- NULL means no readable rule was in force when the record was entered (the setting missing
-- or not a time of day): lateness for that record is UNKNOWN, shown as unknown, never guessed.
--
-- EXISTING ROWS take the setting as it is now, the best available knowledge: nothing records
-- what it was before. (On the cPanel server no attendance row has been written, see 010.)
--
-- NOT DONE HERE, same class of problem: the DEPARTMENT. A record shows the person's CURRENT
-- department. Nothing can change a department yet, so it is hypothetical today; it needs the
-- same snapshot the moment department editing exists (see CLAUDE.md).
BEGIN;

ALTER TABLE attendance_record
  ADD COLUMN late_after_local text
    CONSTRAINT attendance_late_after_local_format_check
    CHECK (late_after_local IS NULL OR late_after_local ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$');

-- The setting's value is a JSON string ('"09:15"'); #>> '{}' takes its text. Anything that is
-- not a time of day leaves the row NULL (unknown) rather than failing or guessing.
UPDATE attendance_record
   SET late_after_local = (SELECT value #>> '{}' FROM setting WHERE key = 'attendance.late_after_local')
 WHERE (SELECT value #>> '{}' FROM setting WHERE key = 'attendance.late_after_local') ~ '^([01][0-9]|2[0-3]):[0-5][0-9]$';

COMMIT;
\echo '>>> applying 017_visit_corrections.sql'
-- 017 the visitor log can be wrong too: corrections, removal, and one open visit each.
--
-- WHY. Check-in and check-out now write real visits (screens 03, 04, 05). The lesson from
-- attendance (014) and movements (015) was that a write path with no way to fix it makes
-- the front desk keep a second paper list. So `visit` gets the same correction columns,
-- BEFORE the first real visit is written rather than after.
--
-- The FULL history of every correction (before and after) is in audit_log. These columns
-- are only so a list can show AT A GLANCE that a visit was changed, by whom, when and why,
-- and they always describe the LATEST correction. correction_reason, corrected_at and
-- corrected_by come together or not at all, exactly as on attendance_record and movement.
--
-- REMOVED IS A VOID, NOT A DELETE (same reasoning as 014): the row stays, with its reason
-- and who removed it, so audit_log, visit_event and any later enquiry or handover still
-- point at something. A voided visit COUNTS FOR NOTHING: it is not "in the building", it is
-- in no count on the dashboard, and it does not stop the same person checking in again. The
-- indexes below exclude it; the application must exclude it from every query of its own.
--
-- ONE OPEN VISIT PER PERSON. A client (by portal id) or a non-client visitor (by visitor
-- row) can be checked in only once at a time: a second check-in while the first is open is
-- a double entry, not a second visit. The application checks it first (under a lock, and
-- names the open visit); these indexes are the backstop. Nothing has written a visit before
-- this migration, so they cannot fail on existing rows.
--
-- AUTO_CLOSED (003) is set only by an EXPLICIT end-of-day action that names the visits, and
-- checked_out_by then records who closed them; checked_out_at is when they were closed, NOT
-- when the visitor left, which nobody recorded. 003's constraints already allow that.

BEGIN;

ALTER TABLE visit
  ADD COLUMN correction_reason text,
  ADD COLUMN corrected_at timestamptz,
  ADD COLUMN corrected_by uuid,
  ADD COLUMN voided_at timestamptz;

ALTER TABLE visit
  ADD CONSTRAINT visit_corrected_by_fkey
    FOREIGN KEY (corrected_by) REFERENCES staff (id);

-- A reason, when present, is never blank (as attendance and movement).
ALTER TABLE visit
  ADD CONSTRAINT visit_correction_reason_not_blank_check
    CHECK (correction_reason IS NULL OR btrim(correction_reason) <> '');

-- When and by whom come together: a correction always says who made it.
ALTER TABLE visit
  ADD CONSTRAINT visit_corrected_pair_check
    CHECK ((corrected_at IS NULL) = (corrected_by IS NULL));

-- And with the reason: a reason without them, or them without a reason, is refused.
ALTER TABLE visit
  ADD CONSTRAINT visit_corrected_matches_reason_check
    CHECK ((correction_reason IS NULL) = (corrected_at IS NULL));

-- A removal is a correction: it carries the reason, the person and the time.
ALTER TABLE visit
  ADD CONSTRAINT visit_voided_needs_correction_check
    CHECK (voided_at IS NULL OR corrected_at IS NOT NULL);

-- Who they came to see, when given, is never blank (the application stores none instead).
ALTER TABLE visit
  ADD CONSTRAINT visit_to_see_not_blank_check
    CHECK (to_see IS NULL OR btrim(to_see) <> '');

CREATE UNIQUE INDEX visit_one_open_per_client_key ON visit (portal_client_id)
  WHERE checked_out_at IS NULL AND voided_at IS NULL AND portal_client_id IS NOT NULL;

CREATE UNIQUE INDEX visit_one_open_per_visitor_key ON visit (visitor_id)
  WHERE checked_out_at IS NULL AND voided_at IS NULL AND visitor_id IS NOT NULL;

COMMIT;
\echo '>>> applying 018_handover_corrections.sql'
-- 018 document handovers: client-only in the database, and corrections that APPEND.
--
-- A handover is the record that documents physically left the building (007). handover and
-- handover_item are APPEND-ONLY and stay so: the triggers of 007 are not touched here. But a
-- desk that cannot fix a mistake keeps a second paper list, so a mistake is answered by a NEW
-- row that points at the old one, never by changing it.
--
-- THE SHAPE, AND WHY.
--  1. handover_correction: a separate, append-only table. One row says "the handover record
--     <handover_id> is wrong", with the reason, who said so and when. The original row and its
--     items stay exactly as written; a correction WITHDRAWS the record (it no longer counts as a
--     release anywhere) and every list shows the original WITH its correction.
--     Not a status column on handover: that would need an UPDATE, which is what the triggers
--     exist to refuse. Not a "correcting" handover row (a self-reference with a kind): a handover
--     row asserts that documents left at released_at, released by someone, under a gate answer
--     the portal gave; a correction asserts none of that, so its gate_answer and released_by
--     would have to be faked, and every count would have to filter kinds. A correction is a
--     statement ABOUT a record, by a person, with a reason: it gets its own table.
--     At most ONE correction per handover (handover_correction_once_key): a withdrawal is final.
--     A withdrawal made by mistake is answered the same way as any other mistake: record the
--     handover again.
--  2. handover.replaces_handover_id: when the release DID happen but was recorded wrongly (two
--     copies, not one; the wrong document), the right one is recorded as a NEW handover, which
--     runs the portal's release-check again at that moment (a correction can never carry an old
--     gate answer onto different documents), and names the withdrawn record it replaces. It is
--     written once, on INSERT, so it needs no UPDATE. A record can be replaced once.
--
-- CLIENT ONLY, IN THE DATABASE. A non-client cannot receive documents. handover gets
-- portal_client_id, and a composite foreign key to visit (id, portal_client_id), the same
-- pattern as case_request (008): a visitor's visit has no portal_client_id, so no handover can
-- reference it. NOT NULL with no default: it fails loudly if any handover row exists, which none
-- does (nothing has written one: 007's tables had no screen until now).
--
-- 007's comment said the application offers "record a handover" only on CHECKED_ALLOWED or
-- NOT_GATED. The owner decided otherwise (see CLAUDE.md, "Document handovers"): a handover made
-- while the gate is OFF or the portal UNAVAILABLE is recorded AS SUCH, plainly unverified,
-- because the documents left either way; CHECKED_BLOCKED stops the desk recording it.

BEGIN;

ALTER TABLE handover
  ADD COLUMN portal_client_id uuid NOT NULL,
  ADD COLUMN replaces_handover_id uuid;

ALTER TABLE handover
  ADD CONSTRAINT handover_visit_is_client_fkey
    FOREIGN KEY (visit_id, portal_client_id) REFERENCES visit (id, portal_client_id);

ALTER TABLE handover
  ADD CONSTRAINT handover_replaces_handover_id_fkey
    FOREIGN KEY (replaces_handover_id) REFERENCES handover (id);

ALTER TABLE handover
  ADD CONSTRAINT handover_not_replacing_itself_check
    CHECK (replaces_handover_id IS NULL OR replaces_handover_id <> id);

-- A note, when there is one, is never blank (the application stores none instead).
ALTER TABLE handover
  ADD CONSTRAINT handover_note_not_blank_check
    CHECK (note IS NULL OR btrim(note) <> '');

CREATE UNIQUE INDEX handover_replaced_once_key ON handover (replaces_handover_id)
  WHERE replaces_handover_id IS NOT NULL;

CREATE TABLE handover_correction (
  id           uuid PRIMARY KEY,
  handover_id  uuid NOT NULL REFERENCES handover (id),
  reason       text NOT NULL
    CONSTRAINT handover_correction_reason_not_blank_check CHECK (btrim(reason) <> ''),
  corrected_by uuid NOT NULL REFERENCES staff (id),
  corrected_at timestamptz NOT NULL DEFAULT now()
);

CREATE UNIQUE INDEX handover_correction_once_key ON handover_correction (handover_id);

-- Append-only, like the record it corrects. The application's database role must also have no
-- UPDATE, DELETE or TRUNCATE on it (a deployment step, as for 007's tables).
CREATE TRIGGER handover_correction_no_row_change
  BEFORE UPDATE OR DELETE ON handover_correction
  FOR EACH ROW EXECUTE PROCEDURE forbid_change();
CREATE TRIGGER handover_correction_no_truncate
  BEFORE TRUNCATE ON handover_correction
  FOR EACH STATEMENT EXECUTE PROCEDURE forbid_change();

COMMIT;
